import{z as A,x as p,o as l,c as m,q as t,j as n,D as r,d as s,s as i,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"Chomsky 层级","description":"","frontmatter":{"title":"Chomsky 层级","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/chomsky-hierarchy.md","filePath":"cs/chomsky-hierarchy.md","lastUpdated":1791063341000}'),h={name:"cs/chomsky-hierarchy.md"};function d(B,a,c,C,f,D){const o=p("Mermaid");return l(),m("div",null,[a[2]||(a[2]=t('<h1 id="chomsky-层级" tabindex="-1">Chomsky 层级 <a class="header-anchor" href="#chomsky-层级" aria-label="Permalink to &quot;Chomsky 层级&quot;">​</a></h1><div class="epigraph"><p>对产生式左端加限制，得到四层语言：正则、上下文无关、上下文有关、递归可枚举；机器一侧依次是有限自动机、下推机、线性有界机、图灵机。</p><footer>—— 据 Chomsky, On Certain Formal Properties of Grammars, 1959；Hopcroft and Ullman 整理</footer></div><p>上一课<a href="/cs/alphabet-language">字母表、串与语言</a>把 \\(L\\) 收成串集，并留下「用什么有限对象去描述它」。本课不重写 \\(\\Sigma^*\\)。缺口是<strong>分层</strong>：同一外延可以有强弱不同的文法，限制产生式形状就得到 Chomsky 四层，后课泵引理、PDA、图灵机都挂在这一格上。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>任意语言都可以写成「枚举其元素的无穷表」，那不是有限描述。文法 \\(G=(V,\\Sigma,P,S)\\) 用有限条产生式生成 \\(L(G)\\)。<span class="marginnote">术语翻译：「产生式」就是替换规则，<code>A → aB</code> 读作「串里的 A 可以换成 aB」。所谓对某一「型」加限制，就是规定规则左边只能长什么样——限制越松，能生成的语言越多，识别它要的机器也越强。</span>不加限制，\\(P\\) 可以模拟任意改写，语言类过大，词法与语法课用过的对象会混在一起。缺口是按左端限制切开：</p><ul><li>3 型（正则）：\\(A\\to aB\\) 或 \\(A\\to a\\)（及 \\(\\varepsilon\\) 变体）。</li><li>2 型（CFG）：\\(A\\to\\alpha\\)。</li><li>1 型（CSG）：\\(|\\alpha|\\le|\\beta|\\) 的上下文改写。</li><li>0 型：无限制，对应递归可枚举。</li></ul><p>主干<a href="/cs/regex-lexer">正则与词法</a>、<a href="/cs/cfg-grammar">CFG</a>已经占用 3 型与 2 型的工程用法。本课给它们在层级里的位置，不重做词法器或推导树。</p><h3 id="包含是真包含" tabindex="-1">包含是真包含 <a class="header-anchor" href="#包含是真包含" aria-label="Permalink to &quot;包含是真包含&quot;">​</a></h3><p>正则 \\(\\subset\\) CFL \\(\\subset\\) CSL \\(\\subset\\) RE，每一层都有严格例子。本课点名形状，不在这里证泵引理——那是后两课的负向工具。0 型与「可判定」不是一回事：RE 可半识别，判定是再下一单元。</p><p><span class="marginnote">Chomsky 1959 比较文法的生成力。Hopcroft–Ullman 把四层与自动机对齐。本栏编译课停在 CFG；CSG 与 LBA 本补层只作层级上的邻居，不写进前端。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把已见对象对号入座：DFA/NFA 认 3 型；CFG 生成 2 型。画出包含链，并声明：证明某 \\(L\\) 落在哪一层，正向给构造，负向给后课引理。不要用「自然语言有多复杂」当例子——那不是形式语言的定理。</p>',12)),(l(),n(E,null,{default:r(()=>[i(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%223%20%E5%9E%8B%20%E6%AD%A3%E5%88%99%20%2F%20DFA%22%5D%20--%3E%20CFL%5B%222%20%E5%9E%8B%20CFL%20%2F%20PDA%22%5D%0A%20%20CFL%20--%3E%20CSL%5B%221%20%E5%9E%8B%20CSL%20%2F%20LBA%22%5D%0A%20%20CSL%20--%3E%20RE%5B%220%20%E5%9E%8B%20RE%20%2F%20TM%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("a",{href:"/cs/nfa-dfa"},"NFA 与 DFA"),s(" 已证正则侧确定与非确定等价。CFG 侧非确定 PDA 严格强于确定 PDA，本课只登记，PDA 课再写。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"层级的用处是禁止越级：词法不用 CFG，语法不用图灵机「随便改写」。越级不是对错，是把判定与复杂度一起抬走——0 型语言的成员问题不可判定。后课每引进一种机器，先问它停在哪一层。",-1)),a[6]||(a[6]=e("p",null,"同一批「数个数」的串，正好把三层卡开：",-1)),(l(),n(E,null,{default:r(()=>[i(o,{id:"mermaid-66",class:"mermaid",graph:"flowchart%20TD%0A%20%20EX1%5B%22a%5En%3A%20%E4%B8%8D%E5%B0%81%E9%A1%B6%E7%9A%84%E9%87%8D%E5%A4%8D%22%5D%20--%3E%20L3%5B%223%20%E5%9E%8B%3A%20%E6%9C%89%E9%99%90%E8%87%AA%E5%8A%A8%E6%9C%BA%E5%8D%B3%E5%8F%AF%22%5D%0A%20%20EX2%5B%22a%5En%20b%5En%3A%20%E8%AE%B0%E4%B8%80%E4%B8%AA%E6%95%B0%22%5D%20--%3E%20L2%5B%222%20%E5%9E%8B%3A%20%E4%B8%8B%E6%8E%A8%E6%9C%BA%E7%9A%84%E6%A0%88%E5%BD%93%E8%AE%A1%E6%95%B0%E5%99%A8%22%5D%0A%20%20EX3%5B%22a%5En%20b%5En%20c%5En%3A%20%E8%AE%B0%E4%B8%A4%E4%B8%AA%E6%95%B0%22%5D%20--%3E%20L1%5B%221%20%E5%9E%8B%3A%20%E8%A6%81%E6%95%B4%E6%9D%A1%E5%B8%A6%E5%AD%90%E6%89%8D%E8%83%BD%E8%AE%B0%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p>正则表达式与 3 型文法等价（Kleene）；本课不重做 Thompson。上下文有关的「上下文」是产生式两侧的串，不是类型环境；名字在<a href="/cs/cfg-grammar">CFG 课</a>已警告过。<span class="marginnote">数字实例：识别 \\(a^3b^3\\)（即 aaabbb）时，有限自动机只有有限个状态，数到第 100 个 a 就「没手指头可掰」；下推机的栈没有这个限制——每读一个 a 压一个盘子，读到 b 再逐个弹，弹完恰好栈空即接受。这就是「一个计数器」 separating 2 型与 3 型的直觉。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证四层严格，不引入线性有界自动机的带子证明。不把 Type-0 写成「所有语言」：所有语言的集合不可数，文法可数，大多数语言无文法。<span class="marginnote">常见误区：初学者容易以为 0 型文法「无所不能、能描述一切语言」。实际上它只能描述可数多个语言（文法是有限字符串），而「所有串的子集」这个全体是不可数的——绝大多数语言连 0 型文法都写不出来，只是它们没法在课上举例子。</span>也不在这里定义图灵机。</p><p>后课默认：谈到正则 / CFL / RE，即 Chomsky 这一格。下一课用泵引理把具体语言从正则里踢出去。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四层由产生式限制定义，并与四类机器对齐。</li><li>真包含；编译前端只用到 3 型与 2 型。</li><li>0 型不是「一切语言」，只是有文法的那可数多个。</li><li>出处：Chomsky, 1959；Hopcroft and Ullman。</li></ul>',6))])}const k=A(h,[["render",d]]);export{b as __pageData,k as default};
